// Simple vector placeholders make expression switching visible before importing art.
function createDemoAssets(){
  const data=svg=>'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)));
  const sprite=(face)=>data(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 700"><path fill="#4d5550" d="M94 245Q65 48 180 48t86 197l-30 48H124z"/><path fill="#f3d9bf" d="M155 238h50v65h-50z"/><path fill="#fcdfc3" d="M111 141q0-73 69-73t69 73v51q-4 67-69 67t-69-67z"/><path fill="#53594e" d="M100 148Q91 51 180 51q98 0 79 103-31-24-45-62-32 44-114 56z"/><path fill="#e5eadb" d="M150 280l30 30 30-30 62 29 37 229H51l37-229z"/><path fill="#3c554c" d="M149 280l31 30-28 58-46-71zM211 280l-31 30 28 58 46-71zM58 523h244l29 122H29z"/><path fill="#c39a76" d="M180 310l-13 42 13 30 13-30z"/><path fill="#f3d9bf" d="M51 499h37v69q-16 24-29 3zM272 499h37l-8 72q-13 21-29-3zM94 645h59v55H94zM207 645h59v55h-59z"/><path fill="#46584d" d="M94 678h59v22H78q0-19 16-22zM207 678h59q16 3 16 22h-75z"/>${face==='微笑'?'<path d="M132 175q14-15 28 0m40 0q14-15 28 0M164 211q16 19 32 0" fill="none" stroke="#5e5d50" stroke-width="5" stroke-linecap="round"/>':face==='惊讶'?'<g fill="#5e5d50"><ellipse cx="147" cy="175" rx="6" ry="11"/><ellipse cx="213" cy="175" rx="6" ry="11"/><ellipse cx="180" cy="214" rx="9" ry="12"/></g>':'<g fill="#5e5d50"><ellipse cx="147" cy="175" rx="6" ry="9"/><ellipse cx="213" cy="175" rx="6" ry="9"/></g><path d="M168 214h24" stroke="#aa7e66" stroke-width="3" stroke-linecap="round"/>'}<g fill="#e9aa96" opacity=".45"><ellipse cx="130" cy="196" rx="13" ry="6"/><ellipse cx="230" cy="196" rx="13" ry="6"/></g></svg>`);
  return ['普通','微笑','惊讶'].map((name,i)=>({id:'demo-sprite-'+i,name:'示例立绘 · '+name,type:'image',data:sprite(name),builtin:true}));
}
